var middleNode = function(head) {
    let slow = head;
    let fast = head;

    // Fast moves 2 steps, slow moves 1 step
    // When fast reaches the end, slow is at the middle
    while (fast && fast.next) {
        slow = slow.next;
        fast = fast.next.next;
    }

    return slow;
};
